"""
name: vocab
description: Pydantic schema for structured vocabulary generation and interactive quiz outputs.
"""

from typing import List, Literal

from pydantic import BaseModel, Field, field_validator


class VocabSchema(BaseModel):
    """Structured vocabulary lesson and multiple-choice quiz generated by the AI Teacher."""

    word: str = Field(description="Target English vocabulary word or phrasal verb")
    phonetic: str = Field(description="IPA phonetic transcription, e.g. /ˈres.ə.pi/")
    part_of_speech: str = Field(description="Part of speech, e.g. noun, verb, adjective")
    definition_vi: str = Field(description="Clear Vietnamese definition")
    definition_en: str = Field(description="Concise English definition")
    example_sentence: str = Field(description="Natural everyday English example sentence")
    example_translation: str = Field(description="Vietnamese translation of the example sentence")
    cefr_level: Literal["A1", "A2", "B1", "B2", "C1", "C2"] = Field(
        default="B1", description="CEFR proficiency level"
    )
    quiz_question: str = Field(
        description="Multiple-choice question testing understanding of the target word"
    )
    quiz_options: List[str] = Field(
        min_length=4,
        max_length=4,
        description="Exactly 4 concise answer choices",
    )
    quiz_correct_index: int = Field(
        ge=0,
        le=3,
        description="Zero-based index (0-3) of the correct option in quiz_options",
    )

    @field_validator("quiz_options")
    @classmethod
    def validate_four_options(cls, options: List[str]) -> List[str]:
        """
        Ensure exactly four non-empty quiz options are provided.

        Parameters:
            options (List[str]): Candidate quiz options.
        Returns:
            List[str]: Validated list of four options.
        """
        cleaned = [opt.strip() for opt in options if opt.strip()]
        if len(cleaned) != 4:
            raise ValueError("quiz_options must contain exactly 4 non-empty options")
        return cleaned


class VocabBatchSchema(BaseModel):
    """Container schema for batch vocabulary extraction and generation."""

    items: List[VocabSchema] = Field(
        default_factory=list,
        description="List of extracted or generated vocabulary lessons; empty if none found",
    )

